CREATE TABLE public.gmail_sync_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),account_id uuid NOT NULL REFERENCES public.email_accounts(id) ON DELETE CASCADE,provider_message_id text NOT NULL CHECK(provider_message_id ~ '^[a-zA-Z0-9_-]{1,200}$'),provenance text NOT NULL CHECK(provenance IN('incremental','seed','expired_history')),history_from text,history_to text NOT NULL,discovered_at timestamptz NOT NULL DEFAULT clock_timestamp(),preexisting boolean NOT NULL DEFAULT false,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','done')),lease_token uuid,lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,message_id uuid REFERENCES public.email_messages(id) ON DELETE SET NULL,outcome text CHECK(outcome IN('inserted','existing','skipped','gone')),completed_at timestamptz,UNIQUE(account_id,provider_message_id));
GRANT SELECT ON public.gmail_sync_queue TO service_role;
REVOKE ALL ON public.gmail_sync_queue FROM anon,authenticated;
ALTER TABLE public.gmail_sync_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY gmail_sync_queue_service_read ON public.gmail_sync_queue FOR SELECT TO service_role USING(true);
CREATE INDEX gmail_sync_queue_pending ON public.gmail_sync_queue(account_id,discovered_at,id) WHERE state='pending';
COMMENT ON TABLE public.gmail_sync_queue IS 'Private durable Gmail receipt; first discovery provenance is immutable, seed/backfill is never upgraded by retry. No message bodies or credentials. Workflow release remains separately blocked.';
CREATE FUNCTION public.gmail_sync_queue_authorize(p_workspace uuid,p_account uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR public.is_read_only_view() OR NOT EXISTS(SELECT 1 FROM public.email_accounts WHERE id=p_account AND workspace_id=p_workspace AND provider='gmail' AND status IN('connected','error')) OR NOT public.sales_account_job_authorize('email_accounts',p_account) THEN RAISE EXCEPTION 'Sincronização Gmail indisponível.' USING ERRCODE='42501';END IF;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_queue_authorize(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.gmail_sync_enqueue(p_workspace uuid,p_account uuid,p_expected_history text,p_next_history text,p_provenance text,p_ids jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE current_history text;n integer;BEGIN PERFORM public.gmail_sync_queue_authorize(p_workspace,p_account);SELECT history_id INTO current_history FROM public.email_accounts WHERE id=p_account AND workspace_id=p_workspace FOR UPDATE;IF current_history IS DISTINCT FROM p_expected_history THEN RAISE EXCEPTION 'Cursor Gmail alterado; repita a sincronização.' USING ERRCODE='40001';END IF;IF p_next_history IS NULL OR p_next_history !~ '^[0-9]{1,40}$' OR p_provenance NOT IN('incremental','seed','expired_history') OR jsonb_typeof(p_ids) IS DISTINCT FROM 'array' OR jsonb_array_length(p_ids)>50000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_ids) v WHERE jsonb_typeof(v)<>'string' OR v#>>'{}' !~ '^[a-zA-Z0-9_-]{1,200}$') OR (p_provenance='incremental' AND p_expected_history IS NULL) OR (p_provenance='seed' AND p_expected_history IS NOT NULL) THEN RAISE EXCEPTION 'Checkpoint Gmail inválido.' USING ERRCODE='22023';END IF;
 INSERT INTO public.gmail_sync_queue(workspace_id,account_id,provider_message_id,provenance,history_from,history_to,preexisting) SELECT p_workspace,p_account,x,p_provenance,p_expected_history,p_next_history,EXISTS(SELECT 1 FROM public.email_messages m WHERE m.account_id=p_account AND m.workspace_id=p_workspace AND m.provider_message_id=x) FROM(SELECT DISTINCT jsonb_array_elements_text(p_ids) x)s ON CONFLICT(account_id,provider_message_id) DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE public.email_accounts SET history_id=p_next_history,last_sync_at=clock_timestamp(),last_error=NULL,status='connected' WHERE id=p_account AND workspace_id=p_workspace;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_enqueue(uuid,uuid,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gmail_sync_enqueue(uuid,uuid,text,text,text,jsonb) TO service_role;
CREATE FUNCTION public.gmail_sync_claim(p_workspace uuid,p_account uuid,p_token uuid) RETURNS SETOF public.gmail_sync_queue LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM public.gmail_sync_queue_authorize(p_workspace,p_account);IF p_token IS NULL THEN RAISE EXCEPTION 'Reserva inválida.';END IF;RETURN QUERY WITH candidates AS(SELECT id FROM public.gmail_sync_queue WHERE workspace_id=p_workspace AND account_id=p_account AND state='pending' AND (lease_until IS NULL OR lease_until<clock_timestamp()) ORDER BY discovered_at,id LIMIT 25 FOR UPDATE SKIP LOCKED) UPDATE public.gmail_sync_queue q SET lease_token=p_token,lease_until=clock_timestamp()+interval '5 minutes',attempts=q.attempts+1 FROM candidates c WHERE q.id=c.id RETURNING q.*;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_claim(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gmail_sync_claim(uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.gmail_sync_finish(p_workspace uuid,p_account uuid,p_id uuid,p_token uuid,p_outcome text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE q record;mid uuid;BEGIN PERFORM public.gmail_sync_queue_authorize(p_workspace,p_account);SELECT * INTO q FROM public.gmail_sync_queue WHERE id=p_id AND account_id=p_account AND workspace_id=p_workspace FOR UPDATE;IF NOT FOUND OR q.state<>'pending' OR q.lease_token IS DISTINCT FROM p_token OR p_token IS NULL THEN RETURN false;END IF;IF p_outcome NOT IN('inserted','existing','skipped','gone') THEN RAISE EXCEPTION 'Resultado inválido.';END IF;SELECT id INTO mid FROM public.email_messages WHERE account_id=p_account AND workspace_id=p_workspace AND provider_message_id=q.provider_message_id;IF p_outcome IN('inserted','existing') AND mid IS NULL THEN RAISE EXCEPTION 'Mensagem Gmail ainda não persistida.';END IF;UPDATE public.gmail_sync_queue SET state='done',message_id=mid,outcome=p_outcome,completed_at=clock_timestamp(),lease_token=NULL,lease_until=NULL WHERE id=q.id;RETURN true;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_finish(uuid,uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gmail_sync_finish(uuid,uuid,uuid,uuid,text) TO service_role;
CREATE FUNCTION public.gmail_sync_retry(p_workspace uuid,p_account uuid,p_id uuid,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE n integer;BEGIN PERFORM public.gmail_sync_queue_authorize(p_workspace,p_account);UPDATE public.gmail_sync_queue SET lease_token=NULL,lease_until=NULL WHERE id=p_id AND workspace_id=p_workspace AND account_id=p_account AND state='pending' AND lease_token=p_token;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_retry(uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gmail_sync_retry(uuid,uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.gmail_sync_provenance_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN IF ROW(NEW.workspace_id,NEW.account_id,NEW.provider_message_id,NEW.provenance,NEW.history_from,NEW.history_to,NEW.discovered_at,NEW.preexisting) IS DISTINCT FROM ROW(OLD.workspace_id,OLD.account_id,OLD.provider_message_id,OLD.provenance,OLD.history_from,OLD.history_to,OLD.discovered_at,OLD.preexisting) THEN RAISE EXCEPTION 'Origem Gmail imutável.' USING ERRCODE='42501';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.gmail_sync_provenance_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER gmail_sync_provenance_guard BEFORE UPDATE ON public.gmail_sync_queue FOR EACH ROW EXECUTE FUNCTION public.gmail_sync_provenance_guard();
NOTIFY pgrst,'reload schema';